import{_ as g,o as y,a as f,c as i,b as e,F as l,r as d,h as v,E as b,f as _,g as r,e as w,w as k,t as s,m as A,y as p,n as m,k as L}from"./index-BT1EsLTl.js";const x={class:"docs-page"},C={class:"docs-inner"},E={class:"sections-grid"},M={class:"section-card__num mono"},S={class:"section-card__title"},T={class:"section-card__desc"},R={key:0,class:"section-card__tags"},D={class:"quick-ref reveal"},O={class:"data-table"},N={class:"mono"},G={class:"mono"},I={__name:"DocsView",setup(V){let o;y(()=>{o=new IntersectionObserver(n=>n.forEach(a=>a.target.classList.toggle("visible",a.isIntersecting)),{threshold:.1}),setTimeout(()=>document.querySelectorAll(".docs-page .reveal").forEach(n=>o.observe(n)),100)}),f(()=>o==null?void 0:o.disconnect());const c=[{id:"overview",num:"01",title:"Project Overview",summary:'When hurricanes and earthquakes knock out the power grid, hospitals and airports rely on backup generators to keep the lights on. We use NASA satellite imagery that captures nighttime lights to detect which critical facilities actually maintained power during 15 major disasters across 17 U.S. states and Turkey (2016–2023). The key insight: areas near facilities with generators stay brighter than their surroundings — we call this the "Resilience Advantage."',tags:["VIIRS VNP46A2","15 Events","Resilience Advantage"]},{id:"data",num:"02",title:"Data Collection & Processing",summary:"No public database of backup generators exists — so we turn to satellite imagery to detect them indirectly. We combine daily nighttime light images from NASA's Black Marble (500m resolution), power outage records from EAGLE-I, and critical facility locations from OpenStreetMap. Each pixel is labeled by its proximity to facilities (buffer zones at 750m/1250m), creating a panel of ~33,700 pixels across 15 events. This section also covers cloud masking, GEE data acquisition, and data quality challenges.",tags:["VNP46A2","EAGLE-I","OSM","Buffer Zones","Cloud QC"]},{id:"eda",num:"03",title:"Exploratory Data Analysis",summary:'Before building models, we need to understand the data. We define the Resilience Ratio (R = NTL/BAU) and discover the "floor effect" — a critical confound where facilities in darker urban cores appear less resilient simply because they start dimmer. We show that different facility types (hospitals vs. fire stations) and city sizes (Miami vs. Lake Charles) produce systematically different resilience signals, with real data visualizations.',tags:["Resilience Ratio","Floor Effect","Facility Groups","City Size"]},{id:"interpretive",num:"04",title:"Interpretive Modeling",summary:"Four statistical models (OLS, MixedLM, Logistic, Cox PH) attack the same hypothesis from different angles — triangulation. Key findings: buffer pixels show +2.8% less NTL decline (MixedLM, p=0.020), 32% lower damage odds (Logit, OR=0.68), and 13% faster recovery (Cox, HR=1.13). But land-use confounding partially explains the effect. LOEO cross-validation reveals severe generalization failure (AUC 0.73→0.45), motivating the predictive modeling phase.",tags:["OLS","MixedLM","Logistic","Cox PH","Triangulation","NLCD Confounding"]},{id:"features",num:"05",title:"Feature Engineering",summary:'We engineer 17 predictive features from the raw data. A key challenge is the "floor effect" — in smaller cities, critical infrastructure is often located in darker areas, which confounds the analysis. We address this with city-level normalization and interaction terms that separate the genuine generator signal from urban brightness patterns.',tags:["17 features","Floor effect","Interactions"]},{id:"models",num:"06",title:"Predictive Models",summary:"Four model variants (A–D) systematically test what drives prediction: Model A uses all features (AUC 0.969), Model B removes pre-NTL (AUC 0.970), Model C adds building footprints (AUC 0.968), and Model D uses pure NTL behavior only (AUC 0.700). The +0.269 AUC gap between A and D quantifies the spatial vs. behavioral signal. 15-fold LOEO cross-validation across 15 events confirms robust generalization.",tags:["RF + XGB","LOEO","4 Model Variants","AUC 0.969"]},{id:"maps",num:"07",title:"Probability Maps",summary:"The trained model scores every urban pixel in each study area with a probability of backup power presence. These probability maps are exported as interactive heatmaps — the red-to-white gradient you see on the Map page. Brighter areas indicate higher predicted likelihood of generator-maintained power during the disaster.",tags:["P_ensemble = 0.7×RF + 0.3×XGB"]},{id:"stage3",num:"08",title:"Stage 3: Zip-Code Analysis",summary:"Do areas with more critical facilities experience less severe power outages? Stage 3 extends the pixel-level analysis to zip-code-level spatial regression. Using EAGLE-I outage records (2014–2023), IBTrACS hurricane tracks, Census ACS demographics, and the Stage 2 backup power probability maps, we test whether facility density and predicted backup power correlate with historical outage severity across ~500 zip codes and 25 disaster events.",tags:["EAGLE-I","Zip Code","Spatial Regression","IBTrACS"]},{id:"web",num:"09",title:"Dashboard Development",summary:"This interactive dashboard is built with Vue 3 + Vite, featuring MapLibre GL JS for WebGL-accelerated map rendering with per-event probability heatmaps, canvas-rendered facility icons, and satellite/vector basemap switching. The site supports mobile responsive layouts, scroll-triggered animations, and is deployed via GitHub Actions to GitHub Pages.",tags:["Vue 3","Vite","MapLibre GL","GitHub Pages"]},{id:"repro",num:"10",title:"Reproducibility",summary:"All data sources are publicly available (NASA, OpenStreetMap, DOE), and the full analysis pipeline is implemented in Jupyter notebooks. This section provides the exact data product IDs, API endpoints, and key academic references needed to reproduce or extend the analysis.",tags:["GEE","Jupyter","Open data"]}];return(n,a)=>{const h=_("RouterLink");return r(),i("div",x,[e("div",C,[a[3]||(a[3]=e("div",{class:"page-header reveal"},[e("div",{class:"tag tag--cyan",style:{"margin-bottom":"10px"}},"Technical Documentation"),e("h1",{class:"page-header__title"},"Methodology & Data"),e("p",{class:"page-header__desc"},' Overview of the analysis pipeline — from satellite data acquisition to predictive modeling. Click "Read More" on any section for detailed technical documentation. ')],-1)),e("div",E,[(r(),i(l,null,d(c,t=>w(h,{key:t.id,to:`/docs/${t.id}`,class:"section-card reveal",style:m({transitionDelay:`${c.indexOf(t)*.06}s`})},{default:k(()=>[e("div",M,s(t.num),1),e("h3",S,s(t.title),1),e("p",T,s(t.summary),1),t.tags?(r(),i("div",R,[(r(!0),i(l,null,d(t.tags,u=>(r(),i("span",{key:u,class:"tag tag--dim"},s(u),1))),128))])):A("",!0),a[0]||(a[0]=e("div",{class:"section-card__cta"},[p(" Read More "),e("span",{class:"arrow"},"→")],-1))]),_:2},1032,["to","style"])),64))]),e("div",D,[a[2]||(a[2]=e("div",{class:"quick-ref__header"},[e("span",{class:"tag tag--amber"},"Quick Reference"),e("span",{style:{"font-size":"11px",color:"var(--text-muted)"}},"Study Events")],-1)),e("div",O,[e("table",null,[a[1]||(a[1]=e("thead",null,[e("tr",null,[e("th",null,"Event"),e("th",null,"Location"),e("th",null,"Year"),e("th",null,"Type"),e("th",null,"Affected")])],-1)),e("tbody",null,[(r(!0),i(l,null,d(v(b),t=>(r(),i("tr",{key:t.id},[e("td",null,[e("span",{class:"dot",style:m({background:t.color})},null,4),p(s(t.name),1)]),e("td",null,s(t.subtitle),1),e("td",N,s(t.year),1),e("td",null,[e("span",{class:L(["tag",`tag--${t.type}`]),style:{"font-size":"10px"}},s(t.type),3)]),e("td",G,s(t.affectedUsers),1)]))),128))])])])])])])}}},z=g(I,[["__scopeId","data-v-7f60ce5a"]]);export{z as default};
